{
  "format": "ariadne-nsd",
  "version": 1,
  "settings": {
    "textKind": "plain",
    "theme": "default",
    "headStyle": "title",
    "locale": "en"
  },
  "diagrams": [
    {
      "id": "d1",
      "head": {
        "kind": "method",
        "text": "rb_insert(T, z)"
      },
      "body": [
        {
          "id": "b1",
          "kind": "process",
          "text": "y = T.nil"
        },
        {
          "id": "b2",
          "kind": "process",
          "text": "x = T.root"
        },
        {
          "id": "b3",
          "kind": "while",
          "text": "x != T.nil",
          "body": [
            {
              "id": "b4",
              "kind": "process",
              "text": "y = x"
            },
            {
              "id": "b5",
              "kind": "if",
              "text": "z.key < x.key",
              "yes": {
                "id": "r1",
                "body": [
                  {
                    "id": "b6",
                    "kind": "process",
                    "text": "x = x.left"
                  }
                ]
              },
              "no": {
                "id": "r2",
                "body": [
                  {
                    "id": "b7",
                    "kind": "process",
                    "text": "x = x.right"
                  }
                ]
              }
            }
          ]
        },
        {
          "id": "b8",
          "kind": "process",
          "text": "z.parent = y"
        },
        {
          "id": "b9",
          "kind": "if",
          "text": "y == T.nil",
          "yes": {
            "id": "r3",
            "body": [
              {
                "id": "b10",
                "kind": "process",
                "text": "T.root = z"
              }
            ]
          },
          "no": {
            "id": "r4",
            "body": [
              {
                "id": "b11",
                "kind": "if",
                "text": "z.key < y.key",
                "yes": {
                  "id": "r5",
                  "body": [
                    {
                      "id": "b12",
                      "kind": "process",
                      "text": "y.left = z"
                    }
                  ]
                },
                "no": {
                  "id": "r6",
                  "body": [
                    {
                      "id": "b13",
                      "kind": "process",
                      "text": "y.right = z"
                    }
                  ]
                }
              }
            ]
          }
        },
        {
          "id": "b14",
          "kind": "process",
          "text": "z.left = z.right = T.nil"
        },
        {
          "id": "b15",
          "kind": "process",
          "text": "z.color = RED"
        },
        {
          "id": "b16",
          "kind": "call",
          "target": {
            "kind": "local",
            "diagram": "d2"
          },
          "args": "T, z",
          "result": ""
        }
      ],
      "folds": [
        {
          "id": "f1",
          "first": "b1",
          "last": "b9",
          "name": "Insert as in a binary search tree"
        }
      ]
    },
    {
      "id": "d2",
      "head": {
        "kind": "method",
        "text": "rb_insert_fixup(T, z)"
      },
      "body": [
        {
          "id": "b17",
          "kind": "while",
          "text": "z.parent.color == RED",
          "body": [
            {
              "id": "b18",
              "kind": "if",
              "text": "z.parent == z.parent.parent.left",
              "yes": {
                "id": "r7",
                "body": [
                  {
                    "id": "b19",
                    "kind": "process",
                    "text": "y = z.parent.parent.right    # uncle"
                  },
                  {
                    "id": "b20",
                    "kind": "if",
                    "text": "y.color == RED",
                    "yes": {
                      "id": "r8",
                      "body": [
                        {
                          "id": "b21",
                          "kind": "process",
                          "text": "z.parent.color = BLACK    # case 1: red uncle"
                        },
                        {
                          "id": "b22",
                          "kind": "process",
                          "text": "y.color = BLACK"
                        },
                        {
                          "id": "b23",
                          "kind": "process",
                          "text": "z.parent.parent.color = RED"
                        },
                        {
                          "id": "b24",
                          "kind": "process",
                          "text": "z = z.parent.parent"
                        }
                      ]
                    },
                    "no": {
                      "id": "r9",
                      "body": [
                        {
                          "id": "b25",
                          "kind": "if",
                          "text": "z == z.parent.right",
                          "yes": {
                            "id": "r10",
                            "body": [
                              {
                                "id": "b26",
                                "kind": "process",
                                "text": "z = z.parent    # case 2: straighten the zigzag"
                              },
                              {
                                "id": "b27",
                                "kind": "call",
                                "target": {
                                  "kind": "local",
                                  "diagram": "d3"
                                },
                                "args": "T, z",
                                "result": ""
                              }
                            ]
                          },
                          "no": {
                            "id": "r11",
                            "body": [
                              {
                                "id": "b28",
                                "kind": "process",
                                "text": ""
                              }
                            ]
                          }
                        },
                        {
                          "id": "b29",
                          "kind": "process",
                          "text": "z.parent.color = BLACK    # case 3"
                        },
                        {
                          "id": "b30",
                          "kind": "process",
                          "text": "z.parent.parent.color = RED"
                        },
                        {
                          "id": "b31",
                          "kind": "call",
                          "target": {
                            "kind": "local",
                            "diagram": "d4"
                          },
                          "args": "T, z.parent.parent",
                          "result": ""
                        }
                      ]
                    }
                  }
                ]
              },
              "no": {
                "id": "r12",
                "body": [
                  {
                    "id": "b32",
                    "kind": "process",
                    "text": "y = z.parent.parent.left    # uncle"
                  },
                  {
                    "id": "b33",
                    "kind": "if",
                    "text": "y.color == RED",
                    "yes": {
                      "id": "r13",
                      "body": [
                        {
                          "id": "b34",
                          "kind": "process",
                          "text": "z.parent.color = BLACK    # case 1: red uncle"
                        },
                        {
                          "id": "b35",
                          "kind": "process",
                          "text": "y.color = BLACK"
                        },
                        {
                          "id": "b36",
                          "kind": "process",
                          "text": "z.parent.parent.color = RED"
                        },
                        {
                          "id": "b37",
                          "kind": "process",
                          "text": "z = z.parent.parent"
                        }
                      ]
                    },
                    "no": {
                      "id": "r14",
                      "body": [
                        {
                          "id": "b38",
                          "kind": "if",
                          "text": "z == z.parent.left",
                          "yes": {
                            "id": "r15",
                            "body": [
                              {
                                "id": "b39",
                                "kind": "process",
                                "text": "z = z.parent    # case 2: straighten the zigzag"
                              },
                              {
                                "id": "b40",
                                "kind": "call",
                                "target": {
                                  "kind": "local",
                                  "diagram": "d4"
                                },
                                "args": "T, z",
                                "result": ""
                              }
                            ]
                          },
                          "no": {
                            "id": "r16",
                            "body": [
                              {
                                "id": "b41",
                                "kind": "process",
                                "text": ""
                              }
                            ]
                          }
                        },
                        {
                          "id": "b42",
                          "kind": "process",
                          "text": "z.parent.color = BLACK    # case 3"
                        },
                        {
                          "id": "b43",
                          "kind": "process",
                          "text": "z.parent.parent.color = RED"
                        },
                        {
                          "id": "b44",
                          "kind": "call",
                          "target": {
                            "kind": "local",
                            "diagram": "d3"
                          },
                          "args": "T, z.parent.parent",
                          "result": ""
                        }
                      ]
                    }
                  }
                ]
              }
            }
          ]
        },
        {
          "id": "b45",
          "kind": "process",
          "text": "T.root.color = BLACK    # the root is always black"
        }
      ]
    },
    {
      "id": "d3",
      "head": {
        "kind": "method",
        "text": "left_rotate(T, x)"
      },
      "body": [
        {
          "id": "b46",
          "kind": "process",
          "text": "y = x.right"
        },
        {
          "id": "b47",
          "kind": "process",
          "text": "x.right = y.left"
        },
        {
          "id": "b48",
          "kind": "if",
          "text": "y.left != T.nil",
          "yes": {
            "id": "r17",
            "body": [
              {
                "id": "b49",
                "kind": "process",
                "text": "y.left.parent = x"
              }
            ]
          },
          "no": {
            "id": "r18",
            "body": [
              {
                "id": "b50",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b51",
          "kind": "process",
          "text": "y.parent = x.parent"
        },
        {
          "id": "b52",
          "kind": "if",
          "text": "x.parent == T.nil",
          "yes": {
            "id": "r19",
            "body": [
              {
                "id": "b53",
                "kind": "process",
                "text": "T.root = y"
              }
            ]
          },
          "no": {
            "id": "r20",
            "body": [
              {
                "id": "b54",
                "kind": "if",
                "text": "x == x.parent.left",
                "yes": {
                  "id": "r21",
                  "body": [
                    {
                      "id": "b55",
                      "kind": "process",
                      "text": "x.parent.left = y"
                    }
                  ]
                },
                "no": {
                  "id": "r22",
                  "body": [
                    {
                      "id": "b56",
                      "kind": "process",
                      "text": "x.parent.right = y"
                    }
                  ]
                }
              }
            ]
          }
        },
        {
          "id": "b57",
          "kind": "process",
          "text": "y.left = x"
        },
        {
          "id": "b58",
          "kind": "process",
          "text": "x.parent = y"
        }
      ]
    },
    {
      "id": "d4",
      "head": {
        "kind": "method",
        "text": "right_rotate(T, x)"
      },
      "body": [
        {
          "id": "b59",
          "kind": "process",
          "text": "y = x.left"
        },
        {
          "id": "b60",
          "kind": "process",
          "text": "x.left = y.right"
        },
        {
          "id": "b61",
          "kind": "if",
          "text": "y.right != T.nil",
          "yes": {
            "id": "r23",
            "body": [
              {
                "id": "b62",
                "kind": "process",
                "text": "y.right.parent = x"
              }
            ]
          },
          "no": {
            "id": "r24",
            "body": [
              {
                "id": "b63",
                "kind": "process",
                "text": ""
              }
            ]
          }
        },
        {
          "id": "b64",
          "kind": "process",
          "text": "y.parent = x.parent"
        },
        {
          "id": "b65",
          "kind": "if",
          "text": "x.parent == T.nil",
          "yes": {
            "id": "r25",
            "body": [
              {
                "id": "b66",
                "kind": "process",
                "text": "T.root = y"
              }
            ]
          },
          "no": {
            "id": "r26",
            "body": [
              {
                "id": "b67",
                "kind": "if",
                "text": "x == x.parent.left",
                "yes": {
                  "id": "r27",
                  "body": [
                    {
                      "id": "b68",
                      "kind": "process",
                      "text": "x.parent.left = y"
                    }
                  ]
                },
                "no": {
                  "id": "r28",
                  "body": [
                    {
                      "id": "b69",
                      "kind": "process",
                      "text": "x.parent.right = y"
                    }
                  ]
                }
              }
            ]
          }
        },
        {
          "id": "b70",
          "kind": "process",
          "text": "y.right = x"
        },
        {
          "id": "b71",
          "kind": "process",
          "text": "x.parent = y"
        }
      ]
    }
  ],
  "view": {
